export function getShuffled<T>(arr: T[]): T[] {
  const copy = [...arr];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

export function getAllWordsForCategory(category: CategoryKey): string[] {
  const preferredLanguage = (i18n?.language as LanguageCode | undefined) ?? "en";
  const languageFallbackOrder: LanguageCode[] = [preferredLanguage, "en", "fa", "sv"];

  const gatherWordsForDisplayName = (displayName: string): string[] => {
    const langBuckets = words[displayName] ?? {};
    const chosenLang = languageFallbackOrder.find((lng) => langBuckets[lng] && Object.keys(langBuckets[lng] as object).length > 0);
    const bucket = (chosenLang ? langBuckets[chosenLang] : undefined) as Partial<Record<Difficulty, string[]>> | undefined;
    if (!bucket) return [];
    const difficulties: Difficulty[] = ["easy", "medium", "hard"];
    const collected: string[] = [];
    for (const d of difficulties) {
      const arr = bucket[d];
      if (Array.isArray(arr)) collected.push(...arr);
    }
    return collected;
  };

  if (category !== "mixedCategory") {
    const displayName = categories[category];
    return gatherWordsForDisplayName(displayName);
  }

  const all: string[] = Object.keys(words)
    .filter((key) => key !== categories.mixedCategory)
    .flatMap((displayName) => gatherWordsForDisplayName(displayName));
  return all;
}
